/* setPushSub */
INSERT INTO TB_PSHSUB (
            USER_NUMB
          , ENDP_URLX
          , P256_KEYX
          , AUTH_KEYX
          , USEE_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{endpUrlx}
          , #{p256Keyx,jdbcType=VARCHAR}
          , #{authKeyx,jdbcType=VARCHAR}
          , #{commYes}
          , CURRENT_TIMESTAMP
          , CURRENT_TIMESTAMP
) AS NEW
ON DUPLICATE KEY UPDATE
       P256_KEYX = NEW.P256_KEYX
     , AUTH_KEYX = NEW.AUTH_KEYX
     , USEE_YSNO = NEW.USEE_YSNO
     , UPDT_DATE = CURRENT_TIMESTAMP

mapper.update:

UPDATE /* uptOtherPushDisabled */
       TB_PSHSUB
   SET USEE_YSNO = #{commNo}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE ENDP_URLX = #{endpUrlx}
   AND USER_NUMB  <>  #{userNumb}
   AND USEE_YSNO  <>  #{commNo}


UPDATE /* delPushSub */
       TB_PSHSUB
   SET USEE_YSNO = #{commNo}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE USER_NUMB = #{userNumb}
   AND ENDP_URLX = #{endpUrlx}


UPDATE /* delAllPushSub */
       TB_PSHSUB
   SET USEE_YSNO = #{commNo}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE USER_NUMB = #{userNumb}
   AND USEE_YSNO  <>  #{commNo}
